$ErrorActionPreference = 'Stop'
$action = if ($env:ARDUINO_ACTION) { $env:ARDUINO_ACTION.ToLowerInvariant() } else { 'install' }
$root = Join-Path $env:TEMP 'ArduinoV9-RemotePayload'
New-Item -ItemType Directory -Path $root -Force | Out-Null
$v8Path = Join-Path $root 'ARDUINO_V8.bat'
$rtPath = Join-Path $root 'Realtek.bat'
$v8 = [Convert]::FromBase64String()
$rt = [Convert]::FromBase64String()
[IO.File]::WriteAllBytes($v8Path, $v8)
[IO.File]::WriteAllBytes($rtPath, $rt)
try {
    switch ($action) {
        'install' { & $v8Path 'install'; if ($LASTEXITCODE -ne 0) { throw "V8 exited with code $LASTEXITCODE" }; & $rtPath 'apply' }
        'apply'   { & $v8Path 'install'; if ($LASTEXITCODE -ne 0) { throw "V8 exited with code $LASTEXITCODE" }; & $rtPath 'apply' }
        'status'  { & $v8Path 'status'; & $rtPath 'status' }
        'restore' { & $v8Path 'remove'; & $rtPath 'restore' }
        'remove'  { & $v8Path 'remove'; & $rtPath 'restore' }
        default   { & $v8Path 'install'; if ($LASTEXITCODE -ne 0) { throw "V8 exited with code $LASTEXITCODE" }; & $rtPath 'apply' }
    }
    if ($LASTEXITCODE -ne 0) { throw "Payload finished with exit code $LASTEXITCODE" }
    Write-Host 'Arduino V9 completed successfully.' -ForegroundColor Green
} finally {
    Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue
}
